function icon_dir(string $sub): string
{
    $d = ICON_DIR . '/' . $sub;
    if (!is_dir($d)) {
        @mkdir($d, 0770, true);
    }
    return $d;
}

/** Geladene Logos: slug => ['title', 'path'] */
/** Logos aus dem Simple-Icons-Import (icons/brands/index.json) – nur diese Datei schreibt der Import. */
function brand_icons_dynamic(): array
{
    $f = ICON_DIR . '/brands/index.json';
    $d = is_file($f) ? json_decode((string)file_get_contents($f), true) : null;
    return is_array($d) ? $d : [];
}

