/** Fest eingebaute Logos (BRAND_BUILTIN). */
function brand_icons_static(): array
{
    return BRAND_BUILTIN;
}

/** Alle Logos: dynamisch (Import) + fest eingebaut (BRAND_BUILTIN). */
function brand_icons(): array
{
    static $idx = null;
    return $idx ??= brand_icons_dynamic() + brand_icons_static();
}

/**
 * Logo passend zum Feld „Betriebssystem“: der längste Logo-Kurzname, der darin vorkommt
 * („Windows Server 2008 R2 Standard“ → windowsserver2008r2, „Debian 13“ → debian) – sonst null.
 */
function brand_for_os(string $os): ?string
{
    static $cache = [];
    $o = preg_replace('/[^a-z0-9]/', '', mb_strtolower($os)) ?? '';
    if ($o === '') {
        return null;
    }
    if (!array_key_exists($o, $cache)) {
        $best = null;
        foreach (array_keys(brand_icons()) as $slug) {
            $slug = (string)$slug;
            if (strlen($slug) >= 4 && str_contains($o, $slug) && ($best === null || strlen($slug) > strlen($best))) {
                $best = $slug;
            }
        }
        $cache[$o] = $best;
    }
    return $cache[$o];
}

function custom_icons(): array
{
    $out = [];
    foreach (glob(ICON_DIR . '/custom/*.{png,jpg,webp,svg}', GLOB_BRACE) ?: [] as $f) {
        $out[] = basename($f);
    }
    sort($out);
    return $out;
}

function icon_valid_value(string $v): bool
{
    if ($v === '') {
        return true;
    }
    if (preg_match('/^g:([a-z0-9-]+)$/', $v, $m)) {
        return isset(HOST_ICONS[$m[1]]);
    }
    if (preg_match('/^b:([a-z0-9]+)$/', $v, $m)) {
        return isset(brand_icons()[$m[1]]);
    }
    return (bool)preg_match('/^c:[0-9a-f]{40}\.(png|jpg|webp|svg)$/', $v) && is_file(ICON_DIR . '/custom/' . substr($v, 2));
}

/** Icon eines Eintrags (eigenes Icon oder nach Typ). */
function host_icon_html(array $h, int $size = 16, string $class = ''): string
{
    $v = (string)($h['icon'] ?? '');
    if (preg_match('/^b:([a-z0-9]+)$/', $v, $m) && isset(brand_icons()[$m[1]])) {
        $b = brand_icons()[$m[1]];
        return '<svg viewBox="0 0 24 24" width="' . $size . '" height="' . $size . '" class="brand-icon ' . h($class) . '" role="img" aria-label="' . h($b['title']) . '"><path fill="currentColor" d="' . h($b['path']) . '"/></svg>';
    }
    if (preg_match('/^c:([0-9a-f]{40}\.(png|jpg|webp|svg))$/', $v, $m)) {
        return '<img src="' . h(url(['a' => 'icon', 'f' => $m[1]])) . '" width="' . $size . '" height="' . $size . '" class="custom-icon ' . h($class) . '" alt="">';
    }
    if (preg_match('/^g:([a-z0-9-]+)$/', $v, $m) && isset(HOST_ICONS[$m[1]])) {
        return icon(HOST_ICONS[$m[1]][0], $size, $class);
    }
    // automatisch: passendes Logo zum Feld „Betriebssystem“, sonst nach Typ
    if ($v === '' && ($slug = brand_for_os((string)($h['os'] ?? ''))) !== null) {
        $b = brand_icons()[$slug];
        return '<svg viewBox="0 0 24 24" width="' . $size . '" height="' . $size . '" class="brand-icon ' . h($class) . '" role="img" aria-label="' . h($b['title']) . '"><path fill="currentColor" d="' . h($b['path']) . '"/></svg>';
    }
    return icon(host_icon($h['kind'] ?? null), $size, $class);
}

/** Auswahlfeld für das Icon (im Formular „Host bearbeiten“). */
function icon_picker(string $current): string
{
    $opt = static function (string $value, string $html, string $label) use ($current): string {
        return '<label class="icon-opt" title="' . h($label) . '" data-label="' . h(mb_strtolower($label)) . '"><input type="radio" name="icon" value="' . h($value) . '"'
            . ($current === $value ? ' checked' : '') . '><span>' . $html . '</span></label>';
    };
    $o = '<div class="icon-picker" id="iconPicker"><div class="icon-picker-head"><input type="search" id="iconFilter" placeholder="' . th('Icons filtern …') . '" autocomplete="off">'
        . '<span class="dim small">' . th('Ausgewählt:') . ' <b id="iconCurrent">' . h($current !== '' ? $current : t('automatisch (nach Typ)')) . '</b></span></div>';
    $o .= '<div class="icon-group"><div class="icon-group-label">' . th('Allgemein') . '</div><div class="icon-grid">'
        . $opt('', icon('x', 20), t('automatisch (nach Typ)'));
    foreach (HOST_ICONS as $k => [$ic, $label]) {
        $o .= $opt('g:' . $k, icon($ic, 22), t($label));
    }
    $o .= '</div></div>';
    $brands = brand_icons();
    $o .= '<div class="icon-group"><div class="icon-group-label">' . th('Betriebssysteme & Software') . ' <span class="dim">(' . th('Simple Icons, CC0 · Windows fest eingebaut') . ')</span></div>';
    if ($brands === []) {
        $o .= '<p class="hint">' . th('Noch keine Logos geladen.') . (can('settings') ? ' <a href="' . h(url(['p' => 'settings']) . '#icons') . '">' . th('Einstellungen → Icons') . '</a>' : '') . '</p>';
    } else {
        $o .= '<div class="icon-grid">';
        foreach ($brands as $slug => $b) {
            $o .= $opt('b:' . $slug, '<svg viewBox="0 0 24 24" width="22" height="22"><path fill="currentColor" d="' . h($b['path']) . '"/></svg>', (string)$b['title']);
        }
        $o .= '</div>';
    }
    $o .= '</div>';
    $custom = custom_icons();
    $o .= '<div class="icon-group"><div class="icon-group-label">' . th('Eigene Icons') . '</div><div class="icon-grid">';
    foreach ($custom as $f) {
        $o .= $opt('c:' . $f, '<img src="' . h(url(['a' => 'icon', 'f' => $f])) . '" width="22" height="22" alt="">', $f);
    }
    $o .= '</div><label class="field"><span>' . th('Eigenes Icon hochladen (PNG, JPG, WebP oder SVG, max. 256 KB)') . '</span>'
        . '<input type="file" name="icon_upload" accept=".png,.jpg,.jpeg,.webp,.svg,image/png,image/jpeg,image/webp,image/svg+xml"></label></div></div>';
    return $o;
}

/** Hochgeladenes Icon prüfen und speichern. Liefert 'c:<datei>' oder wirft. */
function icon_store_upload(array $file): string
{
    if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || !is_uploaded_file((string)$file['tmp_name'])) {
        throw new RuntimeException(t('Upload fehlgeschlagen.'));
    }
    if ((int)$file['size'] > ICON_MAX_BYTES) {
        throw new RuntimeException(t('Icon ist größer als 256 KB.'));
    }
    $data = (string)file_get_contents((string)$file['tmp_name']);
    $ext = icon_detect_type($data);
    if ($ext === null) {
        throw new RuntimeException(t('Nur PNG, JPG, WebP oder SVG (ohne Skripte) erlaubt.'));
    }
    $name = sha1($data) . '.' . $ext;
    $target = icon_dir('custom') . '/' . $name;
    if (!is_file($target) && @file_put_contents($target, $data) === false) {
        throw new RuntimeException(t('Ordner icons/ ist nicht beschreibbar.'));
    }
    @chmod($target, 0640);
    return 'c:' . $name;
}

/** Dateityp am Inhalt erkennen; SVG nur ohne aktive Inhalte. */
function icon_detect_type(string $d): ?string
{
    if (str_starts_with($d, "\x89PNG\r\n\x1a\n")) {
        return 'png';
    }
    if (str_starts_with($d, "\xFF\xD8\xFF")) {
        return 'jpg';
    }
    if (str_starts_with($d, 'RIFF') && substr($d, 8, 4) === 'WEBP') {
        return 'webp';
    }
    $head = ltrim(substr($d, 0, 2048));
    if ((str_starts_with($head, '<svg') || str_starts_with($head, '<?xml')) && str_contains($d, '<svg')
        && !preg_match('/<script|<foreignObject|<iframe|<embed|<object|<!ENTITY|<!DOCTYPE|\son[a-z]+\s*=|javascript:|data:text\/html|(xlink:)?href\s*=\s*["\']\s*(?!#)/i', $d)) {
        return 'svg';
    }
    return null;
}

/** Eigenes Icon ausliefern (?a=icon&f=…). */
function action_icon(): void
{
    $f = get_str('f', 60);
    if (!preg_match('/^[0-9a-f]{40}\.(png|jpg|webp|svg)$/', $f, $m) || !is_file(ICON_DIR . '/custom/' . $f)) {
        http_response_code(404);
        exit;
    }
    session_write_close();
    $types = ['png' => 'image/png', 'jpg' => 'image/jpeg', 'webp' => 'image/webp', 'svg' => 'image/svg+xml'];
    header('Content-Type: ' . $types[$m[1]]);
    header('X-Content-Type-Options: nosniff');
    header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; sandbox");
    header('Cache-Control: private, max-age=86400, immutable');
    readfile(ICON_DIR . '/custom/' . $f);
}

// --- Import der freien Logos (Simple Icons, CC0) ---------------------------------------------

/** Lädt das offizielle npm-Paket „simple-icons“, prüft die Prüfsumme und übernimmt die gewählten Logos. */
function brand_import_online(array $slugs): array
{
    $reg = rtrim((string)setting('system.icons_registry', 'https://registry.npmjs.org/simple-icons'), '/');
    if (!preg_match('#^https://#', $reg)) {
        throw new RuntimeException(t('Die Registry-Adresse muss mit https:// beginnen.'));
    }
    $meta = http_fetch($reg . '/latest', 15, 2097152);
    $j = $meta !== false ? json_decode($meta, true) : null;
    if (!is_array($j) || empty($j['dist']['tarball'])) {
        throw new RuntimeException(t('npm-Registry nicht erreichbar (Proxy unter Einstellungen → Allgemein eintragen oder Paket als .tgz hochladen).'));
    }
    $tarUrl = (string)$j['dist']['tarball'];
    if (parse_url($tarUrl, PHP_URL_HOST) !== parse_url($reg, PHP_URL_HOST)) {
        throw new RuntimeException(t('Unerwartete Download-Adresse: {u}', ['u' => $tarUrl]));
    }
    $tgz = http_fetch($tarUrl, 120, 104857600);
    if ($tgz === false || $tgz === '') {
        throw new RuntimeException(t('Paket konnte nicht geladen werden.'));
    }
    $integrity = (string)($j['dist']['integrity'] ?? '');
    if (preg_match('/^sha512-(.+)$/', $integrity, $m)) {
        if (!hash_equals(base64_decode($m[1]), hash('sha512', $tgz, true))) {
            throw new RuntimeException(t('Prüfsumme des Pakets stimmt nicht – Import abgebrochen.'));
        }
    } elseif (!empty($j['dist']['shasum']) && !hash_equals((string)$j['dist']['shasum'], sha1($tgz))) {
        throw new RuntimeException(t('Prüfsumme des Pakets stimmt nicht – Import abgebrochen.'));
    }
    return brand_import_tgz($tgz, $slugs, 'simple-icons ' . ($j['version'] ?? '?'));
}

/** Logos aus einem simple-icons-.tgz übernehmen (online geladen oder hochgeladen). */
function brand_import_tgz(string $tgz, array $slugs, string $source): array
{
    $want = [];
    foreach ($slugs as $s) {
        if (is_string($s) && isset(BRAND_CATALOG[$s])) {
            $want['package/icons/' . $s . '.svg'] = $s;
        }
    }
    $tar = @gzdecode($tgz, 100 * 1048576); // Schutz vor „Zip-Bomben“
    if ($tar === false) {
        throw new RuntimeException(t('Keine gültige .tgz-Datei.'));
    }
    $found = [];
    $license = null;
    $version = null;
    $off = 0;
    $len = strlen($tar);
    $longName = null;
    while ($off + 512 <= $len) {
        $hdr = substr($tar, $off, 512);
        if (trim($hdr, "\0") === '') {
            break;
        }
        $name = rtrim(substr($hdr, 0, 100), "\0");
        $prefix = rtrim(substr($hdr, 345, 155), "\0");
        if ($prefix !== '') {
            $name = $prefix . '/' . $name;
        }
        if ($longName !== null) {
            $name = $longName;
            $longName = null;
        }
        $size = octdec(trim(substr($hdr, 124, 12), "\0 ")) ?: 0;
        $type = $hdr[156];
        $data = substr($tar, $off + 512, (int)$size);
        $off += 512 + (int)(ceil($size / 512) * 512);
        if ($type === 'L') {
            $longName = rtrim($data, "\0");
            continue;
        }
        if (isset($want[$name])) {
            $found[$want[$name]] = $data;
        } elseif ($name === 'package/LICENSE.md') {
            $license = $data;
        } elseif ($name === 'package/package.json') {
            $version = json_decode($data, true)['version'] ?? null;
        }
    }
    if ($license === null || !str_contains($license, 'CC0')) {
        throw new RuntimeException(t('Das Paket ist nicht „simple-icons“ (CC0-Lizenz nicht gefunden).'));
    }
    $idx = brand_icons_dynamic(); // fest eingebaute Logos nie in index.json übernehmen
    $ok = [];
    foreach ($found as $slug => $svg) {
        $title = preg_match('#<title>(.*?)</title>#s', $svg, $m) ? html_entity_decode($m[1], ENT_QUOTES | ENT_XML1, 'UTF-8') : BRAND_CATALOG[$slug];
        if (!preg_match('#<path d="([MmLlHhVvCcSsQqTtAaZzEe0-9.,\-\s]+)"#', $svg, $m) || strlen($m[1]) > 60000) {
            continue;
        }
        $idx[$slug] = ['title' => mb_substr($title, 0, 60), 'path' => $m[1]];
        $ok[] = $slug;
    }
    ksort($idx);
    $dir = icon_dir('brands');
    file_put_atomic($dir . '/index.json', (string)json_encode($idx, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), 0640);
    file_put_atomic($dir . '/LICENSE-simple-icons.md', "Quelle: " . $source . ($version ? ' (' . $version . ')' : '') . "\nImportiert: " . now_str() . "\n\n" . $license, 0640);
    return ['imported' => $ok, 'missing' => array_values(array_diff(array_values($want), $ok)), 'version' => $version ?? $source];
}
